# Build the generated LVGL Montserrat fonts in fonts/.
#
# They live outside src/ on purpose: they are ~1.6 MB of generated glyph tables
# (~29k lines) that only add noise to repo-wide searches (see .ignore).
# PlatformIO only auto-collects sources under src/, so this PRE script puts them
# back into the build. Recipe: docs/text-lvgl.md; LV_FONT_UI_<S> switches:
# include/lv_conf.h.
#
#   fonts/  — generated by lv_font_conv, never edited by hand
#
# Must be a PRE script: BuildSources() appends to the main program's object list
# and refuses to run once that program is constructed. Because PRE runs before
# the Library Dependency Finder, lvgl's include dir is not on the path yet —
# the fonts `#include "lvgl.h"`, so add it explicitly (derived from the pinned
# lib_deps layout, not a hard-coded version).
from os.path import join

Import("env")

env.Append(CPPPATH=[join("$PROJECT_LIBDEPS_DIR", "$PIOENV", "lvgl")])

env.BuildSources(
    join("$BUILD_DIR", "fonts"),
    join("$PROJECT_DIR", "fonts"),
)
